<script>const salesYears=@json($salesYearContext);function resolveSalesPeriod(){const date=document.querySelector('[name="{{ $dateField }}"]')?.value,box=document.querySelector('#sales-period-context');if(!date)return;const matches=salesYears.filter(year=>date>=year.starts_on&&date<=year.ends_on);if(matches.length!==1){box.className='alert alert-danger mt-3 mb-0';box.textContent='No unique Financial Year exists for '+date+'.';return}const year=matches[0],period=year.periods.find(item=>date>=item.starts_on&&date<=item.ends_on);box.className='alert '+(year.status==='open'&&period?.status==='open'?'alert-info':'alert-warning')+' mt-3 mb-0';box.textContent='Resolved context: Financial Year '+year.name+' ('+year.status+') · Accounting Period '+(period?period.name+' ('+period.status+')':'not configured')}document.querySelector('[name="{{ $dateField }}"]')?.addEventListener('change',event=>{document.querySelector('[name="financial_year_id"]').value='';const period=document.querySelector('[name="accounting_period_id"]');if(period)period.value='';resolveSalesPeriod()});resolveSalesPeriod()</script>
