@if($type!=='receipts')<template id="sales-line-template"><tr><td><select class="form-select item-select" onchange="fillItem(this)"><option value="">Custom line</option>@foreach($items as $item)<option value="{{ $item->id }}" data-description="{{ $item->description ?: $item->name }}" data-price="{{ number_format((float)$item->sales_price,2,'.','') }}" data-account="{{ $item->revenue_account_id }}">{{ $item->code }} — {{ $item->name }}</option>@endforeach</select><input type="hidden" class="revenue-account"></td><td><input class="form-control description" required></td><td><input class="form-control quantity" type="number" min="0.01" step="0.01" value="1.00" required></td><td><input class="form-control price" type="number" min="0" step="0.01" value="0.00" required></td>@if($type!=='credit-notes')<td><input class="form-control discount" type="number" min="0" step="0.01" value="0.00" aria-label="Discount amount"></td>@endif @if(in_array($type,['invoices','credit-notes']))<td><select class="form-select tax-code"><option value="">No tax snapshot</option>@foreach($taxCodes as $taxCode)<option value="{{$taxCode->id}}">{{$taxCode->code}} — {{str($taxCode->treatment)->replace('_',' ')->title()}}</option>@endforeach</select><label class="small"><input type="checkbox" class="tax-inclusive" value="1"> Price includes tax</label></td>@endif<td><button type="button" class="btn btn-sm btn-outline-danger" onclick="removeSalesLine(this)">Remove</button></td></tr></template><script>let nextLine={{count($lines)}};function fillItem(select){let option=select.selectedOptions[0],row=select.closest('tr');if(option.value){row.querySelector('.description').value=option.dataset.description;row.querySelector('.price').value=option.dataset.price;row.querySelector('.revenue-account').value=option.dataset.account}calculateSalesTotals()}function addSalesLine(){let fragment=document.querySelector('#sales-line-template').content.cloneNode(true),row=fragment.querySelector('tr');row.querySelector('.item-select').name=`lines[${nextLine}][item_id]`;row.querySelector('.revenue-account').name=`lines[${nextLine}][revenue_account_id]`;row.querySelector('.description').name=`lines[${nextLine}][description]`;row.querySelector('.quantity').name=`lines[${nextLine}][quantity]`;row.querySelector('.price').name=`lines[${nextLine}][unit_price]`;let discount=row.querySelector('.discount');if(discount)discount.name=`lines[${nextLine}][discount]`;let taxCode=row.querySelector('.tax-code'),taxInclusive=row.querySelector('.tax-inclusive');if(taxCode)taxCode.name=`lines[${nextLine}][tax_code_id]`;if(taxInclusive)taxInclusive.name=`lines[${nextLine}][tax_inclusive]`;document.querySelector('#sales-lines').append(fragment);nextLine++}function removeSalesLine(button){button.closest('tr').remove();calculateSalesTotals()}</script>@endif
@if($type!=='receipts')<script>const salesBody=document.querySelector('#sales-lines'),salesTable=salesBody.closest('table'),amountHeading=document.createElement('th');amountHeading.textContent='Line Amount';salesTable.querySelector('thead tr').insertBefore(amountHeading,salesTable.querySelector('thead tr').lastElementChild);const totalBox=document.createElement('div');totalBox.className='text-end fs-5 fw-bold mb-3';salesTable.parentElement.after(totalBox);function scaledDecimal(value){let text=String(value||'0').trim(),negative=text.startsWith('-');if(negative)text=text.slice(1);let [whole='0',fraction='']=text.split('.');fraction=(fraction+'0000').slice(0,4);let scaled=BigInt(whole||'0')*10000n+BigInt(fraction||'0');return negative?-scaled:scaled}function displayMoney(value){let negative=value<0n;if(negative)value=-value;let cents=(value+50n)/100n,whole=cents/100n,fraction=String(cents%100n).padStart(2,'0');return (negative?'-':'')+whole+'.'+fraction}function calculateSalesTotals(){let total=0n;salesBody.querySelectorAll('tr').forEach(row=>{if(!row.querySelector('.line-amount')){let cell=document.createElement('td');cell.className='line-amount text-end';row.insertBefore(cell,row.lastElementChild)}let quantity=scaledDecimal(row.querySelector('.quantity')?.value),price=scaledDecimal(row.querySelector('.price')?.value),discount=scaledDecimal(row.querySelector('.discount')?.value),amount=(quantity*price)/10000n-discount;row.querySelector('.line-amount').textContent='{{ $company->baseCurrency->code }} '+displayMoney(amount);total+=amount});totalBox.textContent='Document Total: {{ $company->baseCurrency->code }} '+displayMoney(total)}salesBody.addEventListener('input',calculateSalesTotals);salesBody.addEventListener('change',calculateSalesTotals);new MutationObserver(calculateSalesTotals).observe(salesBody,{childList:true});calculateSalesTotals()</script>@endif
